def format_greeting(name, prefix="Hello"):
    return f"{prefix}, {name}!"

name = input().strip()
try:
    custom = input().strip()
except EOFError:
    custom = ""
if custom:
    print(format_greeting(name, prefix=custom))
else:
    print(format_greeting(name))

def sum_to_n(n):
    if n <= 0:
        return 0
    return n + sum_to_n(n - 1)

n = int(input())
print(sum_to_n(n))

def power(base, exp):
    if exp == 0:
        return 1
    return base * power(base, exp - 1)

base = int(input())
exp = int(input())
print(power(base, exp))

def is_leap_year(year):
    return (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0)

def days_in_month(month, year):
    if month < 1 or month > 12:
        return -1
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31

m = int(input())
y = int(input())
print(days_in_month(m, y))

def extract_words(text):
    cleaned = [ch.lower() if ch.isalnum() else " " for ch in text]
    return "".join(cleaned).split()

def analyze_words(words):
    return len(words), len(set(words))

text = input()
words = extract_words(text)
total, unique = analyze_words(words)
print(f"Total: {total}, Unique: {unique}")

def digit_sum(n):
    n = abs(n)
    if n < 10:
        return n
    return (n % 10) + digit_sum(n // 10)

n = int(input())
print(digit_sum(n))

def is_prime(n):
    if n < 2:
        return False
    for d in range(2, int(n ** 0.5) + 1):
        if n % d == 0:
            return False
    return True

def sum_primes(a, b):
    low, high = min(a, b), max(a, b)
    total = 0
    for num in range(low, high + 1):
        if is_prime(num):
            total += num
    return total

a = int(input())
b = int(input())
print(sum_primes(a, b))

def is_palindrome(s, left, right):
    if left >= right:
        return True
    if s[left] != s[right]:
        return False
    return is_palindrome(s, left + 1, right - 1)

s = input().lower()
print("Palindrome" if is_palindrome(s, 0, len(s) - 1) else "Not Palindrome")

def stats(*nums):
    if not nums:
        return None
    low = high = nums[0]
    total = 0
    for x in nums:
        if x < low:
            low = x
        if x > high:
            high = x
        total += x
    return low, high, high - low, total / len(nums)

values = [int(x) for x in input().split()]
res = stats(*values)
if res is None:
    print("No Data")
else:
    low, high, span, avg = res
    print(f"Min: {low}, Max: {high}, Span: {span}, Avg: {avg:.2f}")

def score_to_grade(score):
    if score >= 80:
        return "A+"
    elif score >= 70:
        return "A"
    elif score >= 60:
        return "B"
    elif score >= 50:
        return "C"
    elif score >= 40:
        return "D"
    return "F"

def build_report(records):
    lines = []
    passed = 0
    for name, score in records:
        grade = score_to_grade(score)
        lines.append(f"{name}: {grade}")
        if score >= 40:
            passed += 1
    return lines, passed

n = int(input())
records = []
for _ in range(n):
    name, s = input().split()
    records.append((name, int(s)))

report_lines, pass_count = build_report(records)
for line in report_lines:
    print(line)
print(f"Passed: {pass_count}/{n}")

def apply_mul_div(tokens):
    reduced = [int(tokens[0])]
    i = 1
    while i < len(tokens):
        op = tokens[i]
        val = int(tokens[i + 1])
        if op == "*":
            reduced[-1] *= val
        elif op == "//":
            reduced[-1] //= val
        else:
            reduced.append(op)
            reduced.append(val)
        i += 2
    return reduced

def apply_add_sub(reduced):
    total = reduced[0]
    i = 1
    while i < len(reduced):
        op = reduced[i]
        val = reduced[i + 1]
        if op == "+":
            total += val
        else:
            total -= val
        i += 2
    return total

tokens = input().split()
print(apply_add_sub(apply_mul_div(tokens)))

def fib(n, memo=None):
    if memo is None:
        memo = {0: 0, 1: 1}
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

n = int(input())
print(fib(n))

def is_valid_octet(part):
    if not part:
        return False
    if not all("0" <= ch <= "9" for ch in part):
        return False
    if len(part) > 1 and part[0] == "0":
        return False
    return 0 <= int(part) <= 255

def is_valid_ipv4(addr):
    parts = addr.split(".")
    if len(parts) != 4:
        return False
    return all(is_valid_octet(p) for p in parts)

addr = input().strip()
print("Valid" if is_valid_ipv4(addr) else "Invalid")

import json

def flatten(items, out):
    for x in items:
        if isinstance(x, list):
            flatten(x, out)
        else:
            out.append(str(x))

data = json.loads(input())
result = []
flatten(data, result)
print(" ".join(result) if result else "Empty")

def deposit(accounts, user, amount):
    if amount > 0:
        accounts[user] = accounts.get(user, 0) + amount

def withdraw(accounts, user, amount):
    if amount > 0 and accounts.get(user, 0) >= amount:
        accounts[user] -= amount
        return True
    return False

def transfer(accounts, sender, receiver, amount):
    if sender == receiver or amount <= 0:
        return
    if withdraw(accounts, sender, amount):
        deposit(accounts, receiver, amount)

n = int(input())
accounts = {}
for _ in range(n):
    parts = input().split()
    cmd = parts[0]
    if cmd == "DEPOSIT":
        deposit(accounts, parts[1], int(parts[2]))
    elif cmd == "WITHDRAW":
        withdraw(accounts, parts[1], int(parts[2]))
    elif cmd == "TRANSFER":
        transfer(accounts, parts[1], parts[2], int(parts[3]))

if not accounts:
    print("Empty")
else:
    for user in sorted(accounts):
        print(f"{user}: {accounts[user]}")
